"""Render only residual-FM-qualified comparisons; preserve rejected artifacts."""
from cyclic_followup import *
import html

def main():
    inventory={t['tape']:t for t in json.loads((OUT/'inventory.json').read_text())};tape=inventory['A15_T510077'];bych={c['channel']:c for c in tape['channels']};last=json.loads((OUT/'listening.json').read_text())[-1]
    rendered=[];cards=[]
    for start,offset,label in [(19715.34,last['clip_start']-last['window_start'],'Previously rejected last example'),(44595.55,7.,'Fresh passage: settings frozen before target outcomes')]:
        x,sr,xm=get(bych[15],tape,start,60);ref,sr,rm=get(bych[30],tape,start,60);tr=trajectory(ref,sr,1005.5);new=wide(tr,[2,30]);old=phase_map(ref,sr,1005.5,[4,10]);events=[b for b in beeps(x,sr) if offset+.2<b['start'] and b['end']<offset+11.9]
        clean=x.copy();passes=[]
        if start==19715.34:
            passes=last['cleanup_passes']
            for lines in passes:clean=remove(clean,sr,lines)
        else:
            for _ in range(6):
                lines=detect(clean,sr)
                if not lines:break
                passes.append(lines);clean=remove(clean,sr,lines)
        clean,profile=denoise(clean,sr,reduction_cap_db=6);variants={'before':clean,'rejected_method':resample_at(clean,positions(old,sr,len(clean))),'new_experimental':resample_at(clean,positions(new,sr,len(clean)))}
        lo=round(offset*sr);hi=lo+12*sr;clips={k:v[lo:hi] for k,v in variants.items()}
        reproduction=None
        if start==19715.34:
            original,rate=sf.read(OUT/last['file']);reproduction=float(np.max(abs(clips['before']*last['gain']-original[:12*sr])));assert reproduction<2e-7
        gain=.85/max(np.max(abs(c)) for c in clips.values());tag=f'T510077_{start:.2f}';files={}
        for name,clip in clips.items():
            filename=f'{tag}_{name}.wav';sf.write(DEST/filename,clip*gain,sr,subtype='PCM_24');files[name]=filename
        joined=np.r_[clips['before']*gain,np.zeros(sr),clips['rejected_method']*gain,np.zeros(sr),clips['new_experimental']*gain];sf.write(DEST/f'{tag}_before_rejected_new.wav',joined,sr,subtype='PCM_24')
        actual=[]
        for b in events:
            row=dict(event_start=b['start'],clip_start=b['start']-offset,versions={})
            for name in clips:
                audio,rate=sf.read(DEST/files[name]);amp,freq=burst_track(audio,rate);tt=offset+np.arange(len(freq))/1000
                pos=None if name=='before' else positions(old if name=='rejected_method' else new,sr,len(x));mapped=tt if pos is None else np.interp(tt*sr,np.arange(len(pos)),pos)/sr
                metrics={}
                for margin in [.025,.04,.055]:
                    keep=(mapped>b['start']+margin)&(mapped<b['end']-margin);f=freq[keep];t=tt[keep];basis=np.column_stack([np.ones(len(t)),np.sin(2*np.pi*tr[-1]['dominant_modulation_hz']*t),np.cos(2*np.pi*tr[-1]['dominant_modulation_hz']*t)]);c=np.linalg.lstsq(basis,f,rcond=None)[0]
                    metrics[str(margin)]=dict(rms_hz=float(np.std(f)),rms_cents=float(np.std(1200*np.log2(f/np.median(f)))),cyclic_peak_hz=float(np.hypot(c[1],c[2])))
                row['versions'][name]=metrics
            actual.append(row)
        # Evaluate every rendered beep and all edge masks, not a pooled selected event score.
        qualified=bool(actual) and all(r['versions']['new_experimental'][m]['rms_hz']<12 and r['versions']['new_experimental'][m]['cyclic_peak_hz']<12 and r['versions']['new_experimental'][m]['cyclic_peak_hz']<.25*r['versions']['before'][m]['cyclic_peak_hz'] for r in actual for m in ['0.025','0.04','0.055'])
        if not qualified:raise RuntimeError('Actual rendered residual check failed; do not present as improved')
        delay=cumulative_trapezoid(new,dx=1/200,initial=0);delay-=np.linspace(delay[0],delay[-1],len(delay));tt=np.arange(len(delay))/200;assert np.all(np.diff(tt+delay)>0)
        np.savez_compressed(DEST/f'{tag}_explicit_warp.npz',time_seconds=tt,speed_error=new,displacement_seconds=delay)
        f,t,z=signal.stft(tr[1],200,nperseg=800,noverlap=700);np.savez_compressed(DEST/f'{tag}_nested_spectrum.npz',modulation_hz=f,time_seconds=t,complex_spectrum=z,local_rate_hz=tr[4])
        rendered.append(dict(tape=tape['tape'],window_start=start,clip_offset=offset,reference=rm,target=xm,files=files,combined=f'{tag}_before_rejected_new.wav',gain=gain,cleanup_passes=passes,noise_profile=profile,actual_rendered_events=actual,old_before_reproduction_max_error=reproduction,qualified_numeric_residual=True,listening_acceptance=False))
        players=''.join(f'<div><strong>{title}</strong><audio controls src="{files[name]}"></audio></div>' for name,title in [('before','Cleaned before'),('rejected_method','Rejected correction'),('new_experimental','New experimental correction')])
        cards.append(f'<section><h2>{html.escape(label)}</h2><p>CH15 COMP_SUP, canonical window {start:.2f} s; excerpt offset {offset:.3f} s. One shared gain and identical cleanup.</p>{players}<p><a href="{tag}_before_rejected_new.wav">Combined: 12 s before, 1 s silence, 12 s rejected, 1 s silence, 12 s new</a></p></section>')
    (DEST/'listening.json').write_text(json.dumps(rendered,indent=2));(DEST/'index.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><title>Residual flutter diagnosis</title><style>body{font:18px system-ui;max-width:960px;margin:40px auto;padding:20px;background:#15202b;color:#eee}section{padding:20px;border:1px solid #607080;margin:20px 0}audio{display:block;width:100%;margin:10px 0 20px}a{color:#8cf}</style><h1>Residual flutter: diagnostic comparisons</h1><p>All eight previous canonical examples were rejected by listening. These two new experiments pass explicit residual-cyclic-FM checks on every beep shown, but have NOT been accepted by listening. Do not infer correction of all voices or all channels.</p>'+''.join(cards),encoding='utf-8')
    lastresults=json.loads((DEST/'last_window.json').read_text());fresh=json.loads((DEST/'fresh.json').read_text());follow=json.loads((DEST/'followup.json').read_text())
    lines=['','### Cyclic analysis results and corrected interpretation','','**Concrete diagnosis:** the problematic T510077 reference is centered near 986.28 Hz in this passage, about 19 Hz below the configured 1005.5 Hz capture center. Its dominant fractional-frequency modulation is about 6.55 Hz, drifting approximately 6.548–6.570 Hz within this minute. The previous capture filter loses part of the FM sidebands; simply retaining the right cycle frequency did not retain the correct deviation amplitude/shape. Re-centering the original filter substantially restores the fundamental. A wider isolated-carrier capture plus a 2–30 Hz signed-frequency correction retains additional modulation components and improves the remaining error. These are experiments in isolated research code; the production pipeline is unchanged.','','The last rejected clip contains three beeps at about 1.409, 6.000 and 7.055 seconds in its before segment. The third was omitted from the earlier summary because 2.5-second grouping merged two distinct same-channel beeps. That omission was incorrect for assessing every audible beep; it did not explain the largest residual, because this omitted beep actually improved more than the other two. Every beep is now retained; cross-channel copies are marked as replication rather than independent evidence. The raw-audio detector finds no events on the cleaned 12-second clip with its old thresholds, so actual rendered measurements use source event boundaries explicitly mapped through each timing warp.','','At a 40 ms edge margin, the rejected rendered correction left roughly 28.9, 24.3 and 11.9 cents RMS of pitch variation in those three beeps. Thus a lower score coexisted with substantial residual flutter. No claim is made that a numerical reduction establishes perceptual acceptability. Measurements are repeated with 25/40/55 ms edge exclusions to expose short-event sensitivity. The brief beeps do not independently resolve a 6.55 Hz modulation rate; that rate comes from the continuous reference.','','### Nested spectral experiment','','The first level uses complex carrier demodulation and unwrapped analytic phase to obtain a fractional-frequency trajectory. The second level computes a complex STFT of that signed trajectory, retaining phase rather than using magnitude or AM alone. Local rate estimates allow drift; local phase regressions compare one and three modulation harmonics. A separate broad-band signed-frequency curve retains nonharmonic components. Integrating the speed-error curve produces displacement in seconds; a monotonic inverse time map performs the correction. Explicit speed/displacement curves and complex modulation spectra accompany the new clips.','','The 89 candidate carriers from all 30 channels in the problematic minute did not yield a different-channel, different-frequency harmonic curve with correlation above 0.6 to the principal reference (best approximately 0.43). Consequently no multichannel common-mode correction was authorized. Agreement of the reference with signaling tones may concern a shared incoming feed; the origin of the error and transfer to independent controller voices remain unresolved. Speech-AM periodicity and natural vocal pitch are not used as timing ground truth.','','[Full nested analysis and phase/lag fits](reports/cyclic_flutter_20261017/last_window.json) · [Four-tape factorial comparisons](reports/cyclic_flutter_20261017/followup.json) · [Fresh frozen-method check](reports/cyclic_flutter_20261017/fresh.json) · [New diagnostic listening page](reports/cyclic_flutter_20261017/index.html) · [Actual rendered metrics and paths](reports/cyclic_flutter_20261017/listening.json)','','### Actual residual cyclic flutter in the new clips','','| Window / beep offset | Rejected Hz RMS | New Hz RMS | Rejected 6.55 Hz component, peak Hz | New component, peak Hz |','|---|---:|---:|---:|---:|']
    for rec in rendered:
        for e in rec['actual_rendered_events']:
            a=e['versions']['rejected_method']['0.04'];b=e['versions']['new_experimental']['0.04'];lines.append(f"| {rec['window_start']:.2f} / {e['clip_start']:.3f} s | {a['rms_hz']:.2f} | {b['rms_hz']:.2f} | {a['cyclic_peak_hz']:.2f} | {b['cyclic_peak_hz']:.2f} |")
    lines+=['','The fresh check searched six prespecified, previously untested T510077 positions and found one qualifying passage at 44595.55 s. Its two events appear on CH15 and CH20; those are replicas, not four independent events. The fixed wide method reduced CH15 residual RMS to approximately 7.0 and 5.4 Hz, with fundamental peaks about 2.7 and 3.2 Hz. Wrong-sign and 71 ms shifted controls worsened the same events markedly. This supports local phase-correct FM reduction beyond the problematic example, but does not establish whole-tape or voice quality.','','### What failed or remains uncertain','','- Fitting scale and lag to the first two beeps did not fix the problem robustly: the old-filter fit reached its gain bound and worsened the later held-out beep compared with the uncalibrated old method. The harmonic-fit calibration also retained substantial residual modulation. A fitted −152 ms lag is approximately one modulation period, not proof of a physical channel delay. Periodicity admits ambiguous phase-equivalent delays and sign/half-period combinations.','- Direct phase fitting of one or three harmonics improved the problematic window but left about 15–20 Hz RMS, more than the broad signed-frequency curve. The quasi-periodic rate alone does not describe all instantaneous motion.','- Widening capture around T510073’s low-frequency reference fails: adjacent hum components contaminate phase and the apparent tracked center/rate becomes implausible. Some events worsen by more than a factor of two. Do not transplant the 1 kHz solution to crowded low-frequency references.','- T510075 and T510076 candidate-tone residuals are often small with the wider 1 kHz analysis, but this does not explain away Ben’s rejection of their speech examples. Those examples remain rejected. Controller-voice validation and error provenance remain blockers.','- The new clips qualify only as diagnostic demonstrations of reduced actual cyclic FM, with shared cleanup/gain and every displayed beep checked. They are not listening-accepted, and no full-tape correction is produced.','','### Synthetic checks and limits','','Exact-analysis/resampling tests include centered and 19.2 Hz detuned references, 2.5% and 4% speed modulation, 6.5/8 Hz rates, drifting modulation, added harmonics, AM-only references, gated 250 ms tones, and speech-like material with independent slow natural pitch movement. The original centered sinusoidal tests recover nearly unity fundamental gain, so smoothing alone is not a universal explanation. With detuning and deeper FM the old filter underestimates gain (about 0.84 in one controlled case); re-centering/widening improves it. Harmonic content also leaves residual error when only 4–10 Hz modulation is corrected. Correct-sign/inverse-warp and known 10 ms lag controls behave as expected.','','Unaligned waveform L2 on the speech test initially looked worse because the duration-preserving map leaves a small timing-origin offset (~0.67 ms), to which samplewise audio error is highly sensitive. That score is retained rather than presented as improvement. The additional speech analysis measures the planted FM band directly: approximately 98% lower fractional-frequency RMS while retaining the natural 0.7 Hz pitch variation. It does not establish real speech preservation. AM-only inputs produce essentially zero correction; gain/phase ratios against zero planted FM are mathematically undefined and are stored as null.','','[Initial synthetic cases](reports/cyclic_flutter_20261017/synthetic.json) · [Capture, centering, gated-tone and lag tests](reports/cyclic_flutter_20261017/capture_gain_tests.json) · [Speech-specific synthetic check](reports/cyclic_flutter_20261017/speech_synthetic.json)','','The two-stage treatment of frequency trajectories is consistent with [Marchand and Raspaud’s order-2 sinusoidal modeling](https://www.dafx.de/paper-archive/2004/P_076.PDF), which models frequency and amplitude trajectories separately. That work concerns sound modeling, not evidence that these tapes’ voices share transport flutter. [Maziewski’s modulation-frequency constraints](https://acoustics.ippt.pan.pl/index.php/aa/article/download/639/558/) reinforce the need to measure estimator bandwidth; our conclusions above come from the saved local experiments.','','Reproduce with `python -B research/irig_free_20261016/cyclic_diagnose.py`, then `cyclic_followup.py`, `cyclic_fresh.py`, and `cyclic_report.py`. Outputs are isolated in `reports/cyclic_flutter_20261017/`; old reports/WAVs, source audio and production code are preserved. No concatenation was started, stopped or modified.','']
    report=ROOT/'IRIG_FREE_FLUTTER_RESEARCH.md';current=report.read_bytes();marker=b'\n\n### Cyclic analysis results and corrected interpretation';endmarker=b'<!-- END cyclic analysis 20261017 -->';section='\n'.join(lines).encode()+endmarker+b'\n'
    if marker in current:
        begin=current.index(marker);end=current.find(endmarker,begin)
        if end<0:raise RuntimeError('Refuse replacing an unbounded section')
        new=current[:begin]+section+current[end+len(endmarker):]
    else:new=current+section
    if report.read_bytes()!=current:raise RuntimeError('Concurrent report edit; retry with latest content')
    report.write_bytes(new);print('RENDERED',len(rendered),'comparisons; all shown beeps pass absolute residual checks',flush=True)

if __name__=='__main__':main()
